class InvalidSnapshotException(Exception):
    pass


class NotFoundMandatoryFile(Exception):

    def __init__(self):
        super(NotFoundMandatoryFile, self).__init__("Didn't find all mandatory files.")


class NotExistPath(Exception):

    def __init__(self, path):
        super(NotExistPath, self).__init__("Path: {} doesn't exist.".format(path))


class NotSupportedHardware(Exception):

    def __init__(self, hardware):
        super(NotSupportedHardware, self).__init__("Not supported hardware: {}".format(hardware))


class BrokenArchive(Exception):

    def __init__(self, archives_list):
        super(BrokenArchive, self).__init__("\nCan't open archives:\n{}".format("\n".join(archives_list)))


class FileSizeEqualZero(Exception):

    def __init__(self):
        super(FileSizeEqualZero, self).__init__("File size equal 0 found.")
